const crypto = require('crypto');
const TOKENMGR_PUBKEY = 'p1jdd5yJKobvK0GUMo9VJA/BSdZtCiLzyVel6yOUjVY=';

function b64urlDecode(value) {
  const normalized = String(value || '').replace(/-/g, '+').replace(/_/g, '/');
  const pad = normalized.length % 4;
  const padded = pad ? normalized + '='.repeat(4 - pad) : normalized;
  return Buffer.from(padded, 'base64');
}

function parseTokenPart(part) {
  try {
    return JSON.parse(b64urlDecode(part).toString('utf8'));
  } catch (error) {
    throw new Error(`invalid JWT segment: ${error.message}`);
  }
}

const input = $input.first().json;
const headers = input.headers || {};
const authHeader = headers.authorization || headers.Authorization || '';

function invalid(error) {
  return [{ json: { statusCode: 401, body: { valid: false, error } } }];
}

if (!/^Bearer\s+/i.test(authHeader)) {
  return invalid('Missing Bearer authorization header');
}

const token = authHeader.replace(/^Bearer\s+/i, '').trim();
const parts = token.split('.');
if (parts.length !== 3) {
  return invalid('Token is not a JWT-shaped value');
}

try {
  const header = parseTokenPart(parts[0]);
  const claims = parseTokenPart(parts[1]);
  const signingInput = `${parts[0]}.${parts[1]}`;
  const signature = b64urlDecode(parts[2]);
  const pubKey = crypto.createPublicKey({
    key: {
      kty: 'OKP',
      crv: 'Ed25519',
      x: Buffer.from(TOKENMGR_PUBKEY, 'base64').toString('base64url')
    },
    format: 'jwk'
  });

  if (header.alg !== 'EdDSA') {
    throw new Error(`Unsupported token alg: ${header.alg}`);
  }
  if (!crypto.verify(null, Buffer.from(signingInput), pubKey, signature)) {
    throw new Error('signature does not match');
  }

  return [{ json: { statusCode: 200, valid: true, header, claims, body: { valid: true, header, claims } } }];
} catch (error) {
  return invalid(error.message);
}

const item = $input.first();
const now = Math.floor(Date.now() / 1000);

if (item.json.valid && item.json.claims.exp !== undefined && Number(item.json.claims.exp) <= now) {
  item.json.valid = false;
  item.json.statusCode = 401;
  item.json.body = { valid: false, error: 'Token has expired' };
}

return [item];
